/*
 * Service worker "penghapus diri", menimpa sw.min.js bawaan Chirpy.
 *
 * Service worker Chirpy memakai strategi cache-first untuk semua halaman:
 * sekali halaman menu tersimpan, browser terus menampilkan versi lama itu
 * meski situs sudah di-deploy ulang, bahkan setelah pengunjung "clear cache"
 * biasa. Ini persis masalah screenshot menu versi lama dari pelanggan.
 *
 * PWA sudah dimatikan di _config.yml, jadi skrip ini tidak didaftarkan lagi.
 * File ini tetap ada untuk pengunjung lama yang browsernya masih memegang
 * service worker Chirpy: browser mengecek ulang sw.min.js saat membuka situs,
 * menemukan isinya berubah, lalu memasang versi ini yang langsung menghapus
 * semua cache, mencabut dirinya sendiri, dan memuat ulang tab yang terbuka.
 * Aman dihapus setelah beberapa bulan.
 */
self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      // navigate() hanya boleh untuk tab yang dikendalikan worker ini, jadi
      // ambil alih dulu; tanpa claim() muncul "Cannot navigate to URL".
      await self.clients.claim();
      const clients = await self.clients.matchAll({ type: "window" });
      await self.registration.unregister();
      await Promise.all(
        clients.map((client) => client.navigate(client.url).catch(() => {}))
      );
    })()
  );
});
